[groq-gpt-oss] evals/prompts/lib/skill-p:
Below is a **complete, self-contained TypeScript example** that

1. **creates an IndexedDB database** (`tile-cache`) and stores vector-tile blobs under the key `z/x/y`,
2. **registers a custom `cache://` protocol** with `maplibregl.addProtocol`,
3. **initialises a MapLibre GL JS map** whose style points at `cache://tiles/{z}/{x}/{y}`,
4. **falls back to the network** when a tile is not in the cache,
5. **writes a tile into the cache** (so you can test the whole flow).

You can paste the code into a single HTML file (or split it into modules) and run it in any modern browser.

---

## 1️⃣  Install the tiny `idb` helper (optional but recommended)

```bash
npm i idb
```

`idb` gives a nice Promise-based wrapper around IndexedDB and keeps the code short.

---

## 2️⃣  TypeScript code

```ts
/* --------------------------------------------------------------
   1️⃣  Imports & type helpers
   -------------------------------------------------------------- */
import maplibregl, { Map, MapOptions, RequestParameters, RequestResponse } from 'maplibre-gl';
import { openDB, DBSchema, IDBPDatabase } from 'idb';

/* --------------------------------------------------------------
   2️⃣  Define the IndexedDB schema
   -------------------------------------------------------------- */
interface TileCacheDB extends DBSchema {
  /** One object store per source – we keep it simple and use a single store */
  tiles: {
    key: string;               // “z/x/y” (e.g. “12/3456/7890”)
    value: Uint8Array;         // raw MVT bytes
  };
}

/** Global reference – we open the DB once and reuse it */
let dbPromise: Promise<IDBPDatabase<TileCacheDB>>;

/* --------------------------------------------------------------
   3️⃣  Open (or create) the DB
   -------------------------------------------------------------- */
function initDB(): Promise<IDBPDatabase<TileCacheDB>> {
  if (dbPromise) return dbPromise;

  dbPromise = openDB<TileCacheDB>('tile-cache', 1, {
    upgrade(db) {
      // The store holds raw MVT blobs keyed by “z/x/y”
      db.createObjectStore('tiles');
    },
  });

  return dbPromise;
}

/* --------------------------------------------------------------
   4️⃣  Helper: read a tile from IndexedDB
   -------------------------------------------------------------- */
async function getTileFromCache(z: number, x: number, y: number): Promise<Uint8Array | undefined> {
  const db = await initDB();
  const key = `${z}/${x}/${y}`;
  return db.get('tiles', key);
}

/* --------------------------------------------------------------
   5️⃣  Helper: write a tile into IndexedDB (for demo / testing)
   -------------------------------------------------------------- */
async function putTileIntoCache(z: number, x: number, y: number, data: Uint8Array): Promise<void> {
  const db = await initDB();
  const key = `${z}/${x}/${y}`;
  await db.put('tiles', data, key);
}

/* --------------------------------------------------------------
   6️⃣  Register the custom protocol
   -------------------------------------------------------------- */
maplibregl.addProtocol('cache', async (params: RequestParameters): Promise<RequestResponse> => {
  // params.url looks like:  cache://tiles/12/3456/7890
  // Strip the scheme and any leading slash
  const urlPath = new URL(params.url).pathname.replace(/^\/+/, ''); // "tiles/12/3456/7890"
  const parts = urlPath.split('/');

  // Expect exactly: ["tiles", z, x, y]
  if (parts.length !== 4 || parts[0] !== 'tiles') {
    return {
      // Let the core know we couldn't handle it – it will try the next protocol (or fail)
      data: null,
      cacheControl: null,
      expires: null,
      modified: null,
      etag: null,
      error: new Error(`cache:// URL malformed: ${params.url}`),
    };
  }

  const [, zStr, xStr, yStr] = parts;
  const z = Number(zStr);
  const x = Number(xStr);
  const y = Number(yStr);

  // 1️⃣ Try the cache first
  const cached = await getTileFromCache(z, x, y);
  if (cached) {
    return {
      data: cached.buffer,               // ArrayBuffer (or Uint8Array.buffer)
      cacheControl: null,
      expires: null,
      modified: null,
      etag: null,
    };
  }

  // 2️⃣ Not in cache → fetch from the network, store, then return
  //    (Replace this URL with your real tile endpoint)
  const networkUrl = `https://example.com/tiles/${z}/${x}/${y}.pbf`;

  const response = await fetch(networkUrl);
  if (!response.ok) {
    return {
      data: null,
      cacheControl: null,
      expires: null,
      modified: null,
      etag: null,
      error: new Error(`Network fetch failed: ${networkUrl} – ${response.status}`),
    };
  }

  const arrayBuffer = await response.arrayBuffer();
  const bytes = new Uint8Array(arrayBuffer);

  // Store for next time (fire-and-forget)
  putTileIntoCache(z, x, y, bytes).catch(console.error);

  return {
    data: arrayBuffer,
    cacheControl: response.headers.get('Cache-Control'),
    expires: response.headers.get('Expires'),
    modified: response.headers.get('Last-Modified'),
    etag: response.headers.get('ETag'),
  };
});

/* --------------------------------------------------------------
   7️⃣  Initialise the map – style points at cache://tiles/…
   -------------------------------------------------------------- */
const mapOptions: MapOptions = {
  container: 'map',               // <div id="map"></div> in the HTML
  style: {
    version: 8,
    sources: {
      // The source uses the custom scheme.  The “url” field can be any string;
      // MapLibre will hand it to the protocol handler we just registered.
      myTiles: {
        type: 'vector',
        // Note the trailing slash – MapLibre will replace {z}/{x}/{y}
        url: 'cache://tiles/{z}/{x}/{y}',
        // Optional: tell the renderer the tile size (default 512 for GL-JS)
        tileSize: 512,
      },
    },
    layers: [
      {
        id: 'my-fill',
        type: 'fill',
        source: 'myTiles',
        'source-layer': 'my_layer_name', // <-- change to the layer name inside the MVT
        paint: {
          'fill-color': '#ff6600',
          'fill-opacity': 0.5,
        },
      },
    ],
  },
  center: [0, 0],
  zoom: 2,
};

const map = new Map(mapOptions);

/* --------------------------------------------------------------
   8️⃣  (Optional) Pre-populate the cache for a single tile – handy for demos
   -------------------------------------------------------------- */
async function preloadDemoTile() {
  // Grab a tile from the network once, then store it.
  const demoUrl = 'https://example.com/tiles/2/1/1.pbf';
  const resp = await fetch(demoUrl);
  if (!resp.ok) return;
  const buf = await resp.arrayBuffer();
  await putTileIntoCache(2, 1, 1, new Uint8Array(buf));
}
preloadDemoTile().catch(console.error);
```

---

## 3️⃣  What the code does, step-by-step

| Step | What happens |
|------|--------------|
| **DB init** (`initDB`) | Opens (or creates) an IndexedDB database called **`tile-cache`** with a single object store **`tiles`**. The key is the string `"z/x/y"` and the value is the raw MVT bytes (`Uint8Array`). |
| **`addProtocol('cache', …)`** | Registers a **global** handler for any URL that starts with `cache://`. The handler receives a `RequestParameters` object (the same shape the core uses for HTTP requests). |
| **URL parsing** | The handler extracts `z`, `x`, `y` from the path (`cache://tiles/12/3456/7890`). If the URL does not match the expected pattern, it returns an error so the core can try the next protocol. |
| **Cache lookup** (`getTileFromCache`) | Looks up the tile in IndexedDB. If found, returns the raw `ArrayBuffer`. |
| **Network fallback** | If the tile is missing, the handler fetches it from a regular `https://…` endpoint, stores the result in IndexedDB for future requests, and returns the data to the renderer. |
| **Map creation** | The style references `cache://tiles/{z}/{x}/{y}`. When the map needs a tile, the core calls the protocol handler, which serves the cached bytes (or fetches them). |
| **Demo pre-load** | The optional `preloadDemoTile` shows how you could seed the cache ahead of time (e.g. during an offline-first sync). |

---

## 4️⃣  Things to keep in mind

| Issue | How we handle it |
|-------|------------------|
| **Binary data** – MapLibre expects an `ArrayBuffer` (or `Uint8Array.buffer`). | We return `arrayBuffer` directly. |
| **Headers** – The core may use `Cache-Control`, `ETag`, etc. | We forward the network response headers; for cached tiles we simply omit them (they’re optional). |
| **Error handling** – If the handler returns `null` data **and** an `error`, the map will treat the tile as missing and will try the next protocol (or show a blank tile). | The handler always returns a `RequestResponse` object, never throws. |
| **Threading** – IndexedDB is asynchronous, but the protocol handler can be `async`. MapLibre will `await` the Promise. | The handler is declared `async`. |
| **Multiple sources** – If you have more than one custom source you can either (a) use a different scheme (`cache2://…`) and register another handler, or (b) encode the source name in the path (`cache://mySource/…`). | The example uses a single scheme; you can extend the parser accordingly. |
| **Tile size** – GL JS defaults to 512 px tiles for vector sources. If your source uses 256 px tiles, set `tileSize: 256` in the source definition. | Shown in the source config. |
| **Browser support** – `addProtocol` exists from **MapLibre GL JS 4.0.0** onward. If you run an older version, upgrade. | The code assumes v4+. |

---

## 5️⃣  Full HTML demo (copy-paste)

If you prefer a single-file demo without a build step, here’s a minimal HTML page that bundles the same logic (using the native IndexedDB API instead of `idb` to keep the file self-contained). Replace `https://example.com/…` with a real tile endpoint.

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>MapLibre GL JS – cache:// protocol demo</title>
  <style>
    body, html { margin:0; height:100%; }
    #map { width:100%; height:100%; }
  </style>
  <script src="https://unpkg.com/maplibre-gl@4.4.0/dist/maplibre-gl.js"></script>
  <link href="https://unpkg.com/maplibre-gl@4.4.0/dist/maplibre-gl.css" rel="stylesheet"/>
</head>
<body>
<div id="map"></div>

<script>
  // ---------- 1️⃣  IndexedDB helpers ----------
  const DB_NAME = 'tile-cache';
  const STORE_NAME = 'tiles';
  const DB_VERSION = 1;

  function openDB() {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION);
      request.onupgradeneeded = () => request.result.createObjectStore(STORE_NAME);
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  }

  async function getTile(z, x, y) {
    const db = await openDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const key = `${z}/${x}/${y}`;
      const get = store.get(key);
      get.onsuccess = () => resolve(get.result);
      get.onerror = () => reject(get.error);
    });
  }

  async function putTile(z, x, y, data) {
    const db = await openDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE_NAME, 'readwrite');
      const store = tx.objectStore(STORE_NAME);
      const key = `${z}/${x}/${y}`;
      const put = store.put(data, key);
      put.onsuccess = () => resolve();
      put.onerror = () => reject(put.error);
    });

