## 3️⃣ Register the `cache://` protocol

```ts
// registerCacheProtocol.ts
import maplibregl from 'maplibre-gl';
import { getTile } from './tileCache';

/**
 * The signature required by `addProtocol`:
 *   (params, abortController) => Promise<{ data: ArrayBuffer, ... }>
 *
 * `params` contains:
 *   - url: the full URL that triggered the request (e.g. "cache://tiles/12/3456/7890")
 *   - request: the original Request object (contains method, headers, etc.)
 *
 * We parse the z/x/y from the URL, look it up in IndexedDB,
 * and either resolve with the tile bytes or reject with an error.
 *
 * If you want a network fallback you can simply `fetch()` the same URL
 * after replacing the scheme with `https://…` and return that result.
 */
export function registerCacheProtocol() {
  maplibregl.addProtocol('cache', async (params, abortController) => {
    // --------------------------------------------------------------
    // 1️⃣ Parse z/x/y from the URL
    // --------------------------------------------------------------
    // Expected pattern: cache://tiles/{z}/{x}/{y}
    const match = params.url.match(/^cache:\/\/tiles\/(\d+)\/(\d+)\/(\d+)$/);
    if (!match) {
      // Wrong format – let MapLibre treat it as a normal error
      throw new Error(`cache:// URL not recognised: ${params.url}`);
    }
    const [, zStr, xStr, yStr] = match;
    const z = Number(zStr);
    const x = Number(xStr);
    const y = Number(yStr);

    // --------------------------------------------------------------
    // 2️⃣ Try the IndexedDB cache
    // --------------------------------------------------------------
    const cached = await getTile(z, x, y);
    if (cached) {
      // Success – return the raw MVT bytes.
      // The object shape matches what MapLibre expects from a custom protocol.
      return {
        data: cached,
        // Optional HTTP-like metadata (you can leave them out)
        cacheControl: undefined,
        expires: undefined,
        // The `etag` can be used for conditional requests; we don’t have one.
        etag: undefined,
        // If you want to support aborting a long-running fetch, check abortController.signal.
      };
    }

    // --------------------------------------------------------------
    // 3️⃣ (Optional) Network fallback – replace `cache://` with a real host
    // --------------------------------------------------------------
    // Example: your tiles are also reachable at https://tiles.example.com/{z}/{x}/{y}.pbf
    const fallbackUrl = `https://tiles.example.com/${z}/${x}/${y}.pbf`;
    const response = await fetch(fallbackUrl, { signal: abortController.signal });
    if (!response.ok) {
      throw new Error(`Network fallback failed (${response.status})`);
    }
    const arrayBuffer = await response.arrayBuffer();

    // Store the freshly-fetched tile for next time (fire-and-forget)
    // (You may want to add size-capping, TTL, etc. in a real app)
    putTile(z, x, y, arrayBuffer).catch(console.error);

    return { data: arrayBuffer };
  });
}
```

> **Important:** Call `registerCacheProtocol()` **before** you create the `Map` instance, otherwise the first style load may already have tried (and failed) to fetch the tiles.

