## 5️⃣ Bonus: Pre-populate the cache (e.g. during an offline-first install)

If you want to download a region once and then work completely offline, you can run a one-off “seed” routine:

```ts
import { putTile } from './tileCache';

async function seedRegion(
  sourceUrlTemplate: string, // e.g. "https://tiles.example.com/{z}/{x}/{y}.pbf"
  z: number,
  xRange: [number, number],
  yRange: [number, number]
) {
  const [x0, x1] = xRange;
  const [y0, y1] = yRange;

  for (let x = x0; x <= x1; ++x) {
    for (let y = y0; y <= y1; ++y) {
      const url = sourceUrlTemplate
        .replace('{z}', String(z))
        .replace('{x}', String(x))
        .replace('{y}', String(y));

      try {
        const resp = await fetch(url);
        if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
        const data = await resp.arrayBuffer();
        await putTile(z, x, y, data);
        console.log(`cached ${z}/${x}/${y}`);
      } catch (e) {
        console.warn(`failed ${z}/${x}/${y}:`, e);
      }
    }
  }
}

// Example: cache all tiles for zoom 10 covering the whole world (≈ 1 048 576 tiles)
// In practice you’d limit the area to what you really need.
seedRegion('https://tiles.example.com/{z}/{x}/{y}.pbf', 10, [0, 1023], [0, 1023]);
```

Run this once (e.g. on a “download-offline-data” button) and the map will be able to render completely from the `cache://` scheme thereafter.

