```ts
import maplibregl from 'maplibre-gl';
import { openDB } from 'idb';

// ---- 1️⃣ Open IndexedDB -------------------------------------------------
const dbPromise = openDB('tileCache', 1, {
  upgrade(db) { db.createObjectStore('tiles'); },
});

